def find_weight(fname, slug):
    """Locate a mounted file without assuming the mount depth (ADR-021)."""
    for _d in filter(None, os.environ.get("P28S_WEIGHT_DIRS", "").split(os.pathsep)):   # the local verifier only
        if os.path.exists(os.path.join(_d, fname)):
            return os.path.join(_d, fname)
    for p in (f"/kaggle/input/{slug}/{fname}",
              f"/kaggle/input/datasets/{DOWNER}/{slug}/{fname}"):
        if os.path.exists(p):
            return p
    for d in range(1, 6):
        for hit in sorted(glob.glob("/kaggle/input/" + "*/" * d + fname)):
            if "/competitions/" not in hit:
                return hit
    if os.path.isdir("/kaggle/input"):
        for dp, dn, fn in os.walk("/kaggle/input"):
            dn[:] = [x for x in dn if x != "competitions"]
            if fname in fn:
                return os.path.join(dp, fname)
    raise FileNotFoundError(fname)

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1 << 22), b""):
            h.update(b)
    return h.hexdigest()

