class PlaneHead(nn.Module):
    """Verbatim scripts_p10/p10_10_plane.PlaneHead at n_planes=1.

    Dropout is omitted: no parameters, identity in eval().
    """
    def __init__(s, C=CDIM):
        super().__init__()
        s.C = C
        # C is the backbone's token width: CDIM_B for Bc.  The default keeps
        # PlaneHead() identical to submission 14's head (Lc's, not shipped
        # here), and a head built at the wrong width fails on shape under
        # strict=True instead of scoring quietly -- as ProfHead already does.
        s.proj = nn.ModuleList([nn.Linear(C, DPROJ, bias=False)])
        s.n = nn.LayerNorm(Q * Q * DPROJ)
        s.h = nn.Linear(Q * Q * DPROJ, len(LABELS))
    def forward(s, x):                       # (B, S, Q*Q*CDIM)
        B, S = x.shape[:2]
        x = x.reshape(B, S, 1, Q * Q, s.C)
        z = torch.cat([p(x[:, :, i]) for i, p in enumerate(s.proj)], 2)
        return s.h(s.n(z.reshape(B, S, -1).mean(1)))

class ProfHead(nn.Module):
    """Verbatim scripts_p10/p10_7_a1.ProfHead at agg='prof', proj='learned'.

    The LayerNorm is PER SLICE here, not after pooling, and `a` is a real
    parameter: content-independent position weights, softmax over slices.  That
    is what makes this head NOT permutation-invariant across slices, which is
    why the TTA windows had to be measured on it rather than assumed.
    """
    def __init__(s, S, C=CDIM):
        super().__init__()
        s.S, s.C = S, C
        # C is the backbone's token width: CDIM for every ViT-S member,
        # CDIM_B for B.  The default keeps ProfHead(S) identical to
        # submission 13's head, and a head built at the wrong width fails
        # on shape under strict=True instead of scoring quietly.
        s.proj = nn.Linear(C, DPROJ, bias=False)
        s.n = nn.LayerNorm(Q * Q * DPROJ)
        s.h = nn.Linear(Q * Q * DPROJ, len(LABELS))
        s.a = nn.Parameter(torch.zeros(len(LABELS), S))
    def forward(s, x):                       # (B, S, Q*Q*CDIM)
        B, S = x.shape[:2]
        x = s.proj(x.reshape(B, S, Q * Q, s.C)).reshape(B, S, -1)
        z = s.h(s.n(x))                      # (B, S, L) per-slice logits
        return torch.einsum("bsl,ls->bl", z, torch.softmax(s.a, -1))

