# T:278-286 build_backbone + T:305-332 RaptorClassifier, verbatim (the same text the 1-B probe and
# the 4-D budget kernel ran); the fold state_dicts strict-load into it.  cudnn.benchmark / TF32
# are NOT set: the OOF of record (section 3) was scored without them and the export anchor
# reproduces that OOF at 0.0 on the same path.
# ---- the model: T:278-286 build_backbone (hybrid -> global_pool="avg") + T:305-332 RaptorClassifier, verbatim
def build_backbone(arch, pretrained=False):
    hybrid = arch.startswith(("maxvit", "maxxvit", "coatnet", "coat_", "convnext"))
    is_vit = (not hybrid) and any(k in arch for k in ("vit", "deit", "dinov2", "eva", "beit"))
    kw = dict(pretrained=pretrained, num_classes=0, in_chans=3)
    if is_vit:
        kw.update(global_pool="token", dynamic_img_size=True)
    else:
        kw.update(global_pool="avg")
    return timm.create_model(arch, **kw)

class RaptorClassifier(nn.Module):
    """Raptor encoder + per-diagnosis attention-MIL head (12 findings)."""
    def __init__(self, backbone, F_dim=384, n=12, drop=0.2):
        super().__init__()
        self.backbone = backbone
        self.norm = nn.LayerNorm(F_dim)
        self.att = nn.Sequential(nn.Linear(F_dim, 256), nn.Tanh(), nn.Dropout(drop),
                                 nn.Linear(256, n))
        self.clsW = nn.Parameter(torch.zeros(n, F_dim))
        self.clsb = nn.Parameter(torch.zeros(n))
        nn.init.trunc_normal_(self.clsW, std=0.02)
        self.n = n

    def encode(self, x):
        B, K = x.shape[:2]
        f = self.backbone(x.flatten(0, 1))
        return f.view(B, K, -1)

    def head(self, feats):
        h = self.norm(feats)
        a = self.att(h)
        a = torch.softmax(a, dim=1)
        pooled = torch.einsum("bkn,bkf->bnf", a, h)
        logits = (pooled * self.clsW).sum(-1) + self.clsb
        return logits

    def forward(self, x):
        return self.head(self.encode(x))

# [p73 W17] addendum 7 (the human's decision 16 = H200, 2026-10-20): THE HEARTBEAT INSIDE THE MODEL LOADING.  The parent's heartbeat (T_hb
# from CONST) reads <run_dir>/w<wid>/progress.json's last_update, which the orchestration first writes when this worker is ready (after every
# model below is loaded); until then the parent counts from the spawn.  _w17_beat, called after each model file below, sets last_update = now
# in that file (state "loading", done [] = no study counted; the orchestration's own write at ready replaces it).  Only in the orchestrated
# child (python <worker> <run_dir>/w<wid>_cfg.json); the parent's judgement, T_hb, CHUNK and the deadline are unchanged; nothing is computed
# differently.
_W17 = {"n": 0}


def _w17_beat(member, fold):
    """[p73 W17] the heartbeat point after one model file of the loading: progress.json's last_update = now (no study counted)."""
    _W17["n"] += 1
    try:
        if __name__ != "__main__" or len(sys.argv) < 2 or not sys.argv[1].endswith("_cfg.json") or not os.path.isfile(sys.argv[1]):
            return
        with open(sys.argv[1]) as _f:
            _c = json.load(_f)
        _wd = f"{_c['run_dir']}/w{_c['wid']}"
        if not os.path.isdir(_wd):
            return
        _p = {"wid": _c["wid"], "pid": os.getpid(), "state": "loading", "done": [], "last_update": time.time(),
              "loading": {"files_loaded": _W17["n"], "last": [member, fold]}}
        _tmp = f"{_wd}/progress.json.tmp{os.getpid()}"
        with open(_tmp, "w") as _f:
            json.dump(_p, _f)
        os.replace(_tmp, f"{_wd}/progress.json")
    except Exception:
        pass


