# ============ submission 48 (p67, ADR-119 R1): the tile members' weights are NOT resident on the GPU (the one named edit on p66's cell).
# Each tile fold model is built and strict-loaded on the CPU by p66's loop below (its digest assert unchanged); _r1_hold then points its
# parameters at a read-only memory map of the SAME file (torch.equal asserted tensor by tensor): the weights stay on the worker's CPU side as
# file pages the OS can reclaim, not as ~3 GB of process memory per worker.  In score_study, _r1_infer sends a fold model's parameters to the
# GPU right before infer_e and takes them off right after it (no GPU reference is kept): at most ONE tile model is on the GPU at a time
# (ADR-119 2-B: at most two).  infer_e, the dtype (fp16 autocast, fp32 on RuntimeError), the windows and the inputs are unchanged; the
# copies are exact.  R1_TILE_ON_GPU counts the tile models on the GPU (now / max) and the sends (read by the verifier; printed nowhere).
R1_TILE_ON_GPU = {"now": 0, "max": 0, "sends": 0}
def _r1_hold(m, path):
    """R1: the strict-loaded tile fold model kept on the CPU, its parameters on a memory map of the same file (equal tensor by tensor)."""
    sd = torch.load(path, map_location='cpu', weights_only=True, mmap=True)
    named = list(m.named_parameters()) + list(m.named_buffers())
    assert sorted(n for n, _ in named) == sorted(sd), 'R1: the memory map does not hold the strict-loaded keys'
    for n, t in named:
        assert torch.equal(t.data, sd[n]), f'R1: {n} differs from the strict-loaded value'
        t.data = sd[n]
    m._r1_cpu = [t.data for _, t in named]
    return m.eval()

@torch.no_grad()
def _r1_infer(m, x):
    """R1: the tile fold model to the GPU right before infer_e, off the GPU right after it (the same infer_e, the same model, the same x)."""
    if DEV != 'cuda':
        return infer_e(m, x)
    ts = list(m.parameters()) + list(m.buffers())
    with torch.inference_mode(False):
        for t in ts:
            t.data = t.data.to(DEV)
    R1_TILE_ON_GPU["now"] += 1
    R1_TILE_ON_GPU["sends"] += 1
    R1_TILE_ON_GPU["max"] = max(R1_TILE_ON_GPU["max"], R1_TILE_ON_GPU["now"])
    try:
        return infer_e(m, x)
    finally:
        for t, c in zip(ts, m._r1_cpu):
            t.data = c
        R1_TILE_ON_GPU["now"] -= 1

