# R-8 (ADR-088's 2026-09-21 addendum): a series directory with NO *.dcm falls back to every file in it.  When any *.dcm
# exists this is the decoder's own call, unchanged (the local verifier shows the 64-slice decode is byte-identical).
class _GlobR8:
    @staticmethod
    def glob(pattern):
        import glob as _glob
        fs = _glob.glob(pattern)
        if not fs and pattern.endswith('/*.dcm'):
            fs = sorted(f for f in _glob.glob(pattern[:-len('*.dcm')] + '*') if os.path.isfile(f))
        return fs
