assert RWF_MEMBERS == ['E', 'C', 'A', 'Cnx', 'Anx', 'Xlat', 'Xnotcht', 'Xmed'] and RWF['n_members'] == 8 and len(RWF['mu']) == 96 and float(RWF['eps']) == RW_EPS
assert all(RWF_OUTS[i] == list(range(12)) for i in range(5)) and [RWF_OUTS[RWF_MEMBERS.index(k)] for k in CROP_KEYS] == [sorted(LABELS.index(n) for n in CROP_LABEL_NAME[k]) for k in CROP_KEYS]
RWF_MU, RWF_SD, RWF_W, RWF_B = (np.asarray(RWF[k], np.float64) for k in ('mu', 'sd', 'W', 'b'))
CROP_LABEL = {k: sorted(LABELS.index(n) for n in CROP_LABEL_NAME[k]) for k in CROP_KEYS}   # submission 47 (p64): a list per crop member
def rwf_x(p_by_member):
    """one fold's member-major logits (p18_13_reweight.member_logits_pl's form): each member's DECLARED labels only, eps-clipped,
    0.0 elsewhere; an absent crop member's columns 0.0 (only its own label reads them, and that label is then taken from G1's D)."""
    x = np.zeros(12 * len(RWF_MEMBERS))
    for mi, (mk, outs) in enumerate(zip(RWF_MEMBERS, RWF_OUTS)):
        p = p_by_member.get(mk)
        if p is None:
            continue
        q = np.clip(p[outs], RW_EPS, 1.0 - RW_EPS)
        x[[mi * 12 + j for j in outs]] = np.log(q / (1.0 - q))
    return x
def rwf_z(x):
    return ((x - RWF_MU) / RWF_SD) @ RWF_W + RWF_B
def reweight_f(per_fold):
    """F's D (ADR-115 2-C: the declared per-label member sets), per fold model, then the five sigmoids averaged (ADR-084 2-A-5)."""
    outs = []
    for f in range(5):
        p = {mk: per_fold[mk][f].float().cpu().numpy().astype(np.float64) for mk in RWF_MEMBERS if mk in per_fold}
        z = rwf_z(rwf_x(p))
        outs.append(1.0 / (1.0 + np.exp(-z)))
    return np.mean(outs, 0).astype(np.float32)
