# ONE decode per frame per study for both crops: a thread-local memo on pydicom.dcmread (full reads only; header reads pass through),
# opened and closed around load()'s crop section; outside it pydicom.dcmread is the original
_XMEMO = _xthreading.local()
_X_DCMREAD = _xpydicom.dcmread
def _x_dcmread_once(fp, *a, **kw):
    m = getattr(_XMEMO, 'ds', None)
    if m is None or a or kw:
        return _X_DCMREAD(fp, *a, **kw)
    if fp not in m:
        m[fp] = _X_DCMREAD(fp)
    return m[fp]
_xpydicom.dcmread = _x_dcmread_once

@torch.no_grad()
def infer_e(model, x):
    """I:228-244 infer_probs: fp16 autocast, fp32 on RuntimeError, sigmoid; x (1, 42, 3, 384, 384) on the card -> (12,) probabilities."""
    if DEV == 'cuda':
        try:
            with torch.autocast('cuda', dtype=torch.float16):
                return torch.sigmoid(model(x).float())[0]
        except RuntimeError:
            torch.cuda.empty_cache()
            return torch.sigmoid(model(x).float())[0]
    return torch.sigmoid(model(x).float())[0]

# [p83 L34-W2] 3-2 TAU (EXT-11's [6]; p82 b2a1cdb1): the five whole-knee members' attention sharpened at inference only.  head_tau VERBATIM from scripts_p82/p82_15_tau_score.py; infer_tau = infer_e's path with p82's probs body (one backbone pass, the fp16 autocast, fp32 on a RuntimeError); the member's output = 0.5 x (p_tau12 + p_tau32), float32 (p82's shipped form).
TAU_PAIR = (12.0, 32.0)


def head_tau(model, feats, tau):
    """RaptorClassifier.head with the attention scores multiplied by tau before the softmax over the windows (THE NAMED EDIT)."""
    import torch
    h = model.norm(feats)
    a = model.att(h)
    a = torch.softmax(a * tau, dim=1)
    pooled = torch.einsum("bkn,bkf->bnf", a, h)
    return (pooled * model.clsW).sum(-1) + model.clsb


def infer_tau(model, x):
    """infer_e's path with p82's tau heads: x (1, K, 3, 384, 384) on the card -> (12,) = (sigmoid(tau 12) + sigmoid(tau 32)) x 0.5."""
    def run():
        f = model.encode(x)
        p = [torch.sigmoid(head_tau(model, f, t).float())[0] for t in TAU_PAIR]
        return (p[0] + p[1]) * 0.5
    if DEV == 'cuda':
        try:
            with torch.autocast('cuda', dtype=torch.float16):
                return run()
        except RuntimeError:
            torch.cuda.empty_cache()
            return run()
    return run()

def reweight(per_fold):
    """per_fold: {member: (5, 12) probabilities, one row per fold model}.  For each fold f the four members'
    fold-f outputs (member-major, eps-clipped logits) go through ((x - mu) / sd) @ W + b in float64; the five
    sigmoid outputs are averaged.  NEVER applied to the averaged logits (ADR-084 2-A-5)."""
    outs = []
    for f in range(5):
        p = np.concatenate([per_fold[m][f].float().cpu().numpy().astype(np.float64) for m in RW_MEMBERS])
        q = np.clip(p, RW_EPS, 1.0 - RW_EPS)
        x = np.log(q / (1.0 - q))
        z = ((x - RW_MU) / RW_SD) @ RW_W + RW_B
        outs.append(1.0 / (1.0 + np.exp(-z)))
    return np.mean(outs, 0).astype(np.float32)

