import pydicom
from concurrent.futures import ThreadPoolExecutor

def read_meta(files):
    meta, tag = [], None
    for f in files:
        try:
            d = pydicom.dcmread(f, stop_before_pixels=True)
            ipp = [float(v) for v in getattr(d, "ImagePositionPatient", [0, 0, 0])]
            iop = [float(v) for v in getattr(d, "ImageOrientationPatient",
                                             [1, 0, 0, 0, 1, 0])]
            meta.append((f, ipp, iop))
            if tag is None:
                t = getattr(d, "Laterality", None) or getattr(d, "ImageLaterality", None)
                if t and str(t).upper()[:1] in ("L", "R"):
                    tag = str(t).upper()[:1]
        except Exception:
            continue
    return meta, tag

def ordered_files(st, plane):
    """IPP-ordered file list for one plane, plus the laterality tag it saw."""
    p = PICK[plane]
    if st not in p.index:
        return None, None
    se = p.loc[st, "SeriesInstanceUID"]
    files = glob.glob(f"{ROOT}/test_series/{st}/{se}/*")
    if not files:
        return None, None
    meta, tag = read_meta(files)
    if len(meta) < 2:
        return None, None
    iop0 = np.array(meta[0][2], dtype=float)
    nrm = np.cross(iop0[:3], iop0[3:])
    ax = int(np.argmax(np.abs(nrm)))
    meta.sort(key=lambda m: m[1][ax])
    return [m[0] for m in meta], (tag, float(np.median([m[1][0] for m in meta])))

def read_pixels(path):
    a = np.asarray(pydicom.dcmread(path).pixel_array).astype(np.float32)
    if a.ndim != 2:
        a = a.reshape(-1, *a.shape[-2:])[0]
    return a

def render(files, right, plane):
    """d5_dense_cache.render for the dense positions the three windows need.

    PER-SLICE p1/p99.5, uint8 quantisation, PIL BILINEAR to 224, /255, and the
    float16 store dense_sag.npz applied, read back as float32.

    LATERALITY IS APPLIED HERE AND IT DIFFERS BY PLANE (d5_dense_cache.py:93-94
    and 116-117): sagittal reverses the SLICE ORDER; CORONAL **AND AXIAL**
    mirror the pixels IN PLANE, because both of those planes have an L-R
    in-plane horizontal axis.  d5 tests `plane in ("coronal", "axial")`.
    Submission 10 could write `plane == "coronal"` because coronal was its only
    mirrored plane; COPYING THAT HERE WOULD LEAVE AXIAL UNMIRRORED and still
    produce a perfectly valid submission.csv.
    """
    ps = list(files)
    if right and plane == "sagittal":
        ps = ps[::-1]
    n = len(ps)
    idx = np.clip((FR32 * (n - 1)).round().astype(int), 0, n - 1)
    out = np.zeros((NS, SZ, SZ), np.float16)
    cache = {}
    for k in NEED:
        r = ps[idx[k]]
        a = cache.get(r)
        if a is None:
            a = cache[r] = read_pixels(r)
        lo, hi = np.percentile(a, 1), np.percentile(a, 99.5)
        v = np.clip((a - lo) / max(hi - lo, 1e-6), 0, 1)
        if right and plane in ("coronal", "axial"):
            v = v[:, ::-1]
        im = Image.fromarray((v * 255).astype(np.uint8)).resize((SZ, SZ), Image.BILINEAR)
        out[k] = np.asarray(im, dtype=np.float32) / 255.0
    return out.astype(np.float32)     # the fp16 round trip is above

def preprocess(z):
    z = z.expand(-1, 3, -1, -1)
    m = torch.tensor(IMAGENET_MEAN, device=z.device).view(1, 3, 1, 1)
    s = torch.tensor(IMAGENET_STD, device=z.device).view(1, 3, 1, 1)
    return (z - m) / s

# No frozen `encode` (and no float16 round trip anywhere): the frozen member is
# dropped.  encode_lora / encode_lora_b below are submission 14's, unchanged.
def encode_lora(x, bb):
    """(S,224,224) float32 -> (1, S, Q*Q*CDIM) through ONE adapted backbone.

    The SAME map as `encode` with TWO differences, both deliberate: the
    backbone is the per-fold merged one, and there is NO float16 round trip on
    the patch tokens.  The frozen members were trained on an fp16 feature
    cache and `encode` reproduces that cache; the L member was trained end to
    end on fp32 tokens (p17_common.PixelProfHead.encode) and never saw one.
    Rounding here would still write a valid submission.csv -- with the wrong
    tokens.
    """
    S = x.shape[0]
    t = torch.from_numpy(x).to(DEV).reshape(S, 1, SZ, SZ)
    with torch.no_grad():
        tok = bb.forward_features(preprocess(t))
    p = tok[:, NPRE:].float()
    g = int(round(p.shape[1] ** 0.5))
    b = p.permute(0, 2, 1).reshape(S, CDIM, g, g)
    b = F.adaptive_avg_pool2d(b, Q).reshape(S, CDIM, Q * Q).permute(0, 2, 1)
    return b.reshape(1, S, Q * Q * CDIM)


def encode_lora_b(x, bb):
    """(S,224,224) float32 -> (1, S, Q*Q*CDIM_B) through ONE adapted ViT-B.

    `encode_lora` at the other width, and a SEPARATE function on purpose: a
    single function taking the width as an argument would turn a wrong call
    into a silent reshape deep inside adaptive_avg_pool2d, and that writes a
    valid submission.csv. No float16 round trip here either -- B was trained
    end to end on fp32 tokens, exactly as L was.
    """
    S = x.shape[0]
    t = torch.from_numpy(x).to(DEV).reshape(S, 1, SZ, SZ)
    with torch.no_grad():
        tok = bb.forward_features(preprocess(t))
    p = tok[:, NPRE:].float()
    g = int(round(p.shape[1] ** 0.5))
    b = p.permute(0, 2, 1).reshape(S, CDIM_B, g, g)
    b = F.adaptive_avg_pool2d(b, Q).reshape(S, CDIM_B, Q * Q).permute(0, 2, 1)
    return b.reshape(1, S, Q * Q * CDIM_B)

def load(st):
    """All three planes for one study, with ONE study-level laterality decision.

    The training cache read lat_v3 per STUDY and applied it to whichever plane
    it was building, so the decision is made once here -- from the sagittal
    series, falling back to coronal and then axial, as submissions 5-10 do --
    and used for all three.  IT IS NOT RE-DECIDED PER PLANE.
    """
    # submission 33 (p38): the ViT planes are not read (the ViT members are dropped); E's decode below is the only one.
    g = {}
    _MEMO.px, _MEMO.om = {}, {}                # submission 37 (p41): this study's memo (W6 (i)); closed below
    # E: the 64-slice three-plane stack in the INFERENCE geometry and its windows @384 at EVERY VALID
    # CENTRE, by the embedded decoder -- NO laterality canonicalisation (ADR-087: T+I have none);
    # `right` is not used.  A failure leaves E absent for this study (the mean of the present members,
    # ADR-084 2-A-6).  R-5: an all-zero stack is a failure, not a member.
    try:
        vol, mask = DEC["build_study"](st, SER, SDIR_E, GEOM_INFER)
        if int(np.asarray(mask).sum()) == 0:
            g["E"] = None
        else:
            g["E"] = DEC["eval_windows"](vol, mask, K_E, E_RES)   # (21, 3, 384, 384)  submission 42 (p47): M@21 (ADR-101 2-D; was K_INFER = 42)  submission 21 (p29): G80@42 = E@42's 42 evenly spaced windows (ADR-088 addendum 2-A / 2-D)
    except Exception:
        g["E"] = None
    # submission 37 (p41): C = the coronal-only 40-slice stack, canonicalised.  ONE study-level laterality decision by submission
    # 21's rule (the first plane among sagittal / coronal / axial whose series yields an order: its first Laterality /
    # ImageLaterality tag, else median IPP[0] > 0 -> L else R), then p41_decode.build_study_canon with flip = right and C's 21
    # windows.  A failure, no decision or an all-zero stack leaves C absent (R-5's rule; the mean of the present members).
    g["C"] = None
    g["A"] = None                              # submission 42 (p47): the axial member
    for _xk in CROP_KEYS:                      # submission 46 (p62): the crop members, absent unless drawn below
        g[_xk] = None
    # submission 42 (p47): the laterality decision below is the SAME one (submission 21's rule), taken once and SHARED by C and A.
    right = None
    _sag = None                                # submission 46 (p62): the sagittal list of the decision loop (the crop path reads it)
    try:
        lat = None
        for pl in ("sagittal", "coronal", "axial"):
            _f, _i = ordered_files(st, pl)
            if pl == "sagittal":
                _sag = _f
            if _i is not None:
                lat = _i
                break
        if lat is not None:
            tag, xmed = lat
            if tag is None:
                tag = "L" if xmed > 0 else "R"
            right = tag == "R"
    except Exception:
        right = None
    if right is not None:
        try:
            vc, mc = CANON["build_study_canon"](st, SER, SDIR_E, GEOM_40_COR, right)
            if int(np.asarray(mc).sum()) > 0:
                g["C"] = DEC["eval_windows"](vc, mc, K_COR, E_RES)   # (21, 3, 384, 384)
        except Exception:
            g["C"] = None
        # submission 42 (p47): A = the axial-only 40-slice stack, canonicalised with the same decision (ADR-101 2-B / 2-D); a failure
        # or an all-zero stack leaves A absent (R-5's rule; the mean of the present members).
        try:
            va, ma = CANON["build_study_canon"](st, SER, SDIR_E, GEOM_40_AX, right)
            if int(np.asarray(ma).sum()) > 0:
                g["A"] = DEC["eval_windows"](va, ma, K_AX, E_RES)   # (21, 3, 384, 384)
        except Exception:
            g["A"] = None
        # submission 46 (p62): the crop path (ADR-115 2-F) with the SAME decision `right`: the sagittal series' native frames, ONE decode
        # per frame for both crops (the memo), each crop drawn by its builder's own function (embedded) -> its 21 windows; a failure, no
        # sagittal list or an all-zero stack leaves that crop absent (its label then comes from G1's D)
        if _sag is not None:
            _XMEMO.ds = {}
            _XSAG.st, _XSAG.files = st, _sag
            _XSAG.se = PICK["sagittal"].loc[st, "SeriesInstanceUID"] if st in PICK["sagittal"].index else None
            try:
                if "Xlat" in CROP_KEYS:
                    try:
                        _v, _m, _r = XL.build_one(st, right, {k: {"box": tuple(v["box"]), "range": tuple(v["range"])} for k, v in GEO_LAT.items()})
                        if int(np.asarray(_m["lat"]).sum()) > 0:
                            g["Xlat"] = DEC["eval_windows"](_v["lat"], _m["lat"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xlat"] = None
                if "Xnotcht" in CROP_KEYS:
                    try:
                        _tg = {"centre": tuple(TG_NOTCH["centre"]), "side": float(TG_NOTCH["side"]), "range": tuple(TG_NOTCH["range"]),
                               "min_slices": int(TG_NOTCH["min_slices"])}
                        _v, _m, _r = XN.build_one_tile(st, right, _tg)
                        if int(np.asarray(_m["notch"]).sum()) > 0:
                            g["Xnotcht"] = DEC["eval_windows"](_v["notch"], _m["notch"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xnotcht"] = None
                if "Xmed" in CROP_KEYS:              # submission 47 (p64): X_med = X_lat's slot, the builder's own build_one on region med
                    try:
                        _v, _m, _r = XL.build_one(st, right, {k: {"box": tuple(v["box"]), "range": tuple(v["range"])} for k, v in GEO_MED.items()})
                        if int(np.asarray(_m["med"]).sum()) > 0:
                            g["Xmed"] = DEC["eval_windows"](_v["med"], _m["med"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xmed"] = None
                if "Xmedt" in TILE_KEYS:              # submission 48 (p66): the tile Xmedt = X_notch_t's slot, its embedded drawing function on Xmedt's constants
                    try:
                        _tg = {"centre": tuple(TG_XMEDT["centre"]), "side": float(TG_XMEDT["side"]), "range": tuple(TG_XMEDT["range"]),
                               "min_slices": int(TG_XMEDT["min_slices"])}
                        _v, _m, _r = XN.build_one_tile(st, right, _tg)    # the drawing's output key is X_notch_t's "notch"
                        if int(np.asarray(_m["notch"]).sum()) > 0:
                            g["Xmedt"] = DEC["eval_windows"](_v["notch"], _m["notch"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xmedt"] = None
                if "Xlatt" in TILE_KEYS:              # submission 48 (p66): the tile Xlatt = X_notch_t's slot, its embedded drawing function on Xlatt's constants
                    try:
                        _tg = {"centre": tuple(TG_XLATT["centre"]), "side": float(TG_XLATT["side"]), "range": tuple(TG_XLATT["range"]),
                               "min_slices": int(TG_XLATT["min_slices"])}
                        _v, _m, _r = XN.build_one_tile(st, right, _tg)    # the drawing's output key is X_notch_t's "notch"
                        if int(np.asarray(_m["notch"]).sum()) > 0:
                            g["Xlatt"] = DEC["eval_windows"](_v["notch"], _m["notch"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xlatt"] = None
                if "Xpft" in TILE_KEYS:              # submission 48 (p66): the tile Xpft = X_notch_t's slot, its embedded drawing function on Xpft's constants
                    try:
                        _tg = {"centre": tuple(TG_XPFT["centre"]), "side": float(TG_XPFT["side"]), "range": tuple(TG_XPFT["range"]),
                               "min_slices": int(TG_XPFT["min_slices"])}
                        _v, _m, _r = XN.build_one_tile(st, right, _tg)    # the drawing's output key is X_notch_t's "notch"
                        if int(np.asarray(_m["notch"]).sum()) > 0:
                            g["Xpft"] = DEC["eval_windows"](_v["notch"], _m["notch"], K_X, E_RES)   # (21, 3, 384, 384)
                    except Exception:
                        g["Xpft"] = None
            finally:
                _XMEMO.ds = None
                _XSAG.st, _XSAG.files, _XSAG.se = None, None, None
    _MEMO.px, _MEMO.om = None, None            # submission 37 (p41): the study's memo closed (W6 (i))
    if all(v is None for v in g.values()):
        return st, None
    return st, g


