def score_study(g):
    """Submission 18's main-loop body for ONE study (its lines, dedented one level; the counters go to `info`, and
    the probabilities are returned instead of written to `pred`).  Returns (q (12,) float64, 15 NaN, info)."""
    info = {"e_absent": 0, "fix_member": 0, "fix_prior": 0, "no_member": 0, "part": 0, "e_k": None}
    with torch.inference_mode():
        member, per_fold = {}, {}
        # submission 33 (p38): no ViT member (dropped, ADR-096 2-C V9_S42_drop).
        # E: the windows (every valid centre) through the five fold models (I:415-433 runs the
        # folds in sequence), the shipped fp16 path; no TTA.  Absent when its decode failed or
        # its stack was all zero (R-5).
        if g.get("E") is not None:
            xe = g["E"].unsqueeze(0).to(DEV)
            info["e_k"] = int(g["E"].shape[0])
            per_fold["E"] = torch.stack([infer_tau(m, xe) for m in e_models], 0)   # (5, 12)   [p83 L34-W3] tau 12 / 32, their mean (was infer_e)
            member["E"] = per_fold["E"].mean(0)
            # submission 42 (p47): M_s2's forward on E's windows removed (the S slot is not in V15_M21)
            del xe
        else:
            info["e_absent"] = 1
        # submission 37 (p41): C = M_cor on ITS OWN 21 windows of the coronal 40-slice stack (absent when its render failed)
        if g.get("C") is not None:
            xc = g["C"].unsqueeze(0).to(DEV)
            per_fold["C"] = torch.stack([infer_tau(m, xc) for m in c_models], 0)   # (5, 12)   [p83 L34-W3] tau 12 / 32, their mean (was infer_e)
            member["C"] = per_fold["C"].mean(0)
            # submission 43 (p53): Cnx = M_cor_nx on the SAME windows tensor (xc = the C slot's stack), the same infer_e
            per_fold["Cnx"] = torch.stack([infer_tau(m, xc) for m in cnx_models], 0)   # (5, 12)   [p83 L34-W3] tau 12 / 32, their mean (was infer_e)
            member["Cnx"] = per_fold["Cnx"].mean(0)
            del xc
        else:
            info["c_absent"] = 1                    # submission 37: counted by the orchestration (O3)
        # submission 42 (p47): A = M_ax on ITS OWN 21 windows of the axial 40-slice stack (absent when its render failed)
        if g.get("A") is not None:
            xa = g["A"].unsqueeze(0).to(DEV)
            per_fold["A"] = torch.stack([infer_tau(m, xa) for m in a_models], 0)   # (5, 12)   [p83 L34-W3] tau 12 / 32, their mean (was infer_e)
            member["A"] = per_fold["A"].mean(0)
            # submission 43 (p53): Anx = M_ax_nx on the SAME windows tensor (xa = the A slot's stack), the same infer_e
            per_fold["Anx"] = torch.stack([infer_tau(m, xa) for m in anx_models], 0)   # (5, 12)   [p83 L34-W3] tau 12 / 32, their mean (was infer_e)
            member["Anx"] = per_fold["Anx"].mean(0)
            del xa
        else:
            info["a_absent"] = 1                    # submission 42: counted by the orchestration (O3)
        # submission 46 (p62): the crop members on THEIR OWN 21 windows (absent when drawn nothing); NOT in `member` = the stack-absent mean
        # never takes a crop member (ADR-115 2-F)
        for _xk, _xmods in (("Xlat", xlat_models), ("Xnotcht", xnotcht_models), ("Xmed", xmed_models)):   # submission 47 (p64): + X_med
            if g.get(_xk) is not None:
                xx = g[_xk].unsqueeze(0).to(DEV)
                per_fold[_xk] = torch.stack([infer_e(m, xx) for m in _xmods], 0)   # (5, 12)
                del xx
            else:
                info[_xk.lower() + "_absent"] = 1   # counted by the orchestration (O3)
        # submission 48 (p66): the tile members on THEIR OWN 21 windows (the crop loop's copy); a non-finite output on its labels = the
        # tile absent (its labels then come from F19's D); NOT in `member` (the stack-absent mean never takes a tile, ADR-118 2-F)
        for _tk, _tmods in (("Xmedt", xmedt_models), ("Xlatt", xlatt_models), ("Xpft", xpft_models),):
            if g.get(_tk) is not None:
                xx = g[_tk].unsqueeze(0).to(DEV)
                _pt = torch.stack([_r1_infer(m, xx) for m in _tmods], 0)   # (5, 12)  p67 R1 (ADR-119): to the GPU right before, off right after
                del xx
                if bool(torch.isfinite(_pt[:, TILE_LABEL[_tk]]).all()):
                    per_fold[_tk] = _pt
                else:
                    info[_tk.lower() + "_absent"] = 1
            else:
                info[_tk.lower() + "_absent"] = 1   # counted by the orchestration (O3)
        if not member:
            info["no_member"] = 1                  # submission 18: `continue` (the row stays at PRIOR, not scored)
            return np.full(len(LABELS), np.nan), np.full(15, np.nan), info
        # (a scored study: counted by the orchestration)
        if len(member) < 5:                    # submission 43 (p53): 5 members
            info["part"] = 1
        # THE REWEIGHTER NEEDS ALL FOUR MEMBERS (its inputs are the four fold-f outputs);
        # with all four present it is applied per fold model and the five sigmoids are
        # averaged (ADR-084 2-A-5).  Otherwise THE MEAN IS RETAKEN OVER THE MEMBERS
        # PRESENT (ADR-084 2-A-6): a study with no axial series is scored by the
        # equal-weight mean of B+Bc+E.  Never zero-filled.
        if len(member) == 5:                   # submission 43 (p53): all 5 members
            q = reweight_g(per_fold)           # submission 48 (p66): F20's D (the declared per-label member sets)
            _ta = [k for k in TILE_KEYS if k not in per_fold]
            if _ta:                            # submission 48 (p66): a tile absent: ITS labels from F19's D (submission 47's reweighter)
                _qf = reweight_f(per_fold)
                for _k in _ta:
                    q[TILE_LABEL[_k]] = _qf[TILE_LABEL[_k]]
            _xa = [k for k in CROP_KEYS if k not in per_fold]
            if _xa:                            # a crop absent: ITS label from G1's D (submission 43's reweighter), the others F's
                _qg = reweight(per_fold)
                for _k in _xa:
                    q[CROP_LABEL[_k]] = _qg[CROP_LABEL[_k]]
        else:
            q = torch.stack(list(member.values()), 0).mean(0).float().cpu().numpy()
        # R-6: a non-finite cell is replaced by THIS study's finite members' mean at that label,
        # and by PRIOR when no member is finite there.  Counted, never silent.
        q = np.asarray(q, np.float64)
        if not np.isfinite(q).all():
            mv = np.stack([member[m].float().cpu().numpy().astype(np.float64) for m in member], 0)
            for j, lb in enumerate(LABELS):
                if np.isfinite(q[j]):
                    continue
                col = mv[:, j]
                good = col[np.isfinite(col)]
                if good.size:
                    q[j] = float(good.mean()); info["fix_member"] += 1
                else:
                    q[j] = PRIOR[lb]; info["fix_prior"] += 1
    return q, np.full(15, np.nan), info


gpu_out = score_study

